from typing import Dict, List

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.components.cell.cloud_cell import CloudCell
from taf.rfrl.procedures.resources.python.bts.components.du.du import Du
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_info, log_debug, pretty_log
from taf.rfrl.procedures.resources.python.bts.utils.timer import is_in_utc_format
from taf.rfrl.procedures.resources.python.bts.utils.measurements import is_measurement_numeric


def general_siso_auto_cloud_rf_diagnostic_test(testing_env: TestingEnv, cell_name: str):
    """
    Based on:
    QC Test ID: 36445
    QC Test Name: [1.0] CB006992_34_OAM_TDD_SA_Initiate_RF_diagnostic_test_per_cell_and_all_cells_deletion_Results_via_NOM_DC

    Should report to:
    QC Test ID: 70616
    QC Test Name: General_SiSo_Auto_Cloud_RF_Diagnostic_Test

    :param testing_env: testing environment prepared for this test case
    :param cell_name: name of cell for which RF Diagnostic Test should be run;
                      can be taken from "NRCELL ID" field of cell details in DU WebEM;
                      i.e. 'NRCELL-1'
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    bts.cells.check_if_name_exists(name=cell_name)

    for du in bts.dus:
        try:
            _start_rf_diagnostic_test_for_selected_cell(du, cell_name)
            _validate_rf_diagnostic_test_results_for_selected_cell(du, cell_name)
            _clear_rf_diagnostic_test_results(du)
            _start_rf_diagnostic_test_for_all_cells_from_nr_rat(du)
            _validate_rf_diagnostic_test_results_for_all_cells_from_nr_rat(du)
        except ResultError as exc:
            errors.add_from_exception(exc)

    errors.check()


def teardown_for_general_siso_auto_rf_diagnostic_test(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]

    for du in bts.dus:
        _clear_rf_diagnostic_test_results(du)
        du.check_state(state='on_air')


def _start_rf_diagnostic_test_for_selected_cell(du: Du, cell_name: str):
    cell = du.cells.find_by_name(name=cell_name,
                                 raise_exc=True)

    du.rf_diagnostic_test.run_rf_diagnostic_test(cell=cell)


@pretty_log
def _validate_rf_diagnostic_test_results_for_selected_cell(du: Du, cell_name: str):
    cell = du.cells.find_by_name(cell_name)
    test_results_from_api = du.rf_diagnostic_test.get_rf_diagnostic_test_results()
    dist_name = f'MRBTS-{{}}/MNL-1/MNLENT-1/TEST-1/RFREQ-0/RFRES-{cell.id}'
    test_results_from_config = du.config.get_many(dist_names=[dist_name])
    _validate_rf_diagnostic_test_results(test_results_from_api,
                                         test_results_from_config,
                                         cells=[cell])


def _clear_rf_diagnostic_test_results(du: Du):
    du.rf_diagnostic_test.clear_rf_diagnostic_test_results()


def _start_rf_diagnostic_test_for_all_cells_from_nr_rat(du: Du):
    du.rf_diagnostic_test.run_rf_diagnostic_test(cell=None)


@pretty_log
def _validate_rf_diagnostic_test_results_for_all_cells_from_nr_rat(du: Du):
    nr_cells = [cell for cell in du.cells if cell.rat == 'NR']
    test_results_from_api = du.rf_diagnostic_test.get_rf_diagnostic_test_results()
    test_results_from_config = {}

    for cell in nr_cells:
        dist_name = du.config.format_dist_name(f'MRBTS-{{}}/MNL-1/MNLENT-1/TEST-1/RFREQ-1/RFRES-{cell.id}')
        test_results_from_config[dist_name] = du.config.get_many(dist_names=[dist_name])[dist_name]

    _validate_rf_diagnostic_test_results(test_results_from_api,
                                         test_results_from_config,
                                         cells=nr_cells)


@pretty_log
def _validate_rf_diagnostic_test_results(api_results: Dict, config_results: Dict, cells: List[CloudCell]):
    errors = []

    for cell in cells:
        log_info(f'Validating RF Diagnostic test results for {cell.name}', to_console=True)

        source = 'API response'
        api_result_for_cell = _get_api_result_for_cell(api_results, cell, errors)

        if api_result_for_cell:
            _validate_start_time(api_result_for_cell['general_test_info']['actual_start_time'], cell, errors, source)
            _validate_stop_time(api_result_for_cell['general_test_info']['actual_stop_time'], cell, errors, source)
            _validate_test_outcome(api_result_for_cell['general_test_info']['test_outcome'],
                                   api_result_for_cell['general_test_info']['fwd_test_disp'],
                                   api_result_for_cell['general_test_info']['rvrs_test_disp'],
                                   cell, errors, source)
            _validate_antennas_results_from_api(api_result_for_cell['general_test_info']['detailed_result'], cell, errors)

        source = 'DU configuration'
        config_result_for_cell = _get_config_result_for_cell(config_results, cell, errors)

        if config_result_for_cell:
            _validate_start_time(config_result_for_cell['actualStartTime'], cell, errors, source)
            _validate_stop_time(config_result_for_cell['actualStopTime'], cell, errors, source)
            _validate_test_outcome(config_result_for_cell['testOutcome'],
                                   config_result_for_cell['fwdTestDisp'],
                                   config_result_for_cell['rvrsTestDisp'],
                                   cell, errors, source)
            _validate_antennas_results_from_config(config_result_for_cell['rfAntResults'], cell, errors)

    if errors:
        error_msg = 'Validation of RF Diagnostic test results failed due to following errors:'

        for error in errors:
            error_msg += f'\n{error}'

        raise ResultError(error_msg)


def _get_api_result_for_cell(results: Dict, cell: CloudCell, errors: List[str]) -> Dict:
    log_debug(f'Getting test results for {cell.name} from API response')
    result_for_cell = None

    for result in results['rf_diagnostic_test_results']:
        if str(result['nr_cell_id']) == cell.id:
            result_for_cell = result
            break

    if not result_for_cell:
        errors.append(f'{cell.name}: no test results for this cell in API response')

    return result_for_cell


def _get_config_result_for_cell(results: Dict, cell: CloudCell, errors: List[str]) -> Dict:
    log_debug(f'Getting test results for {cell.name} from DU configuration')
    result_for_cell = None

    for dist_name, result in results.items():
        if dist_name.endswith(f'RFRES-{cell.id}'):
            result_for_cell = result
            break

    if not result_for_cell:
        errors.append(f'{cell.name}: no test results for this cell in DU configuration')

    return result_for_cell


def _validate_start_time(start_time: str, cell: CloudCell, errors: List[str], source: str):
    log_debug(f'Validating test start time for {cell.name} in {source}')

    if not is_in_utc_format(date_time=start_time):
        errors.append(f'{cell.name}: test start time {start_time} not in UTC format in {source}')


def _validate_stop_time(stop_time: str, cell: CloudCell, errors: List[str], source: str):
    log_debug(f'Validating test stop time for {cell.name} in {source}')

    if not is_in_utc_format(date_time=stop_time):
        errors.append(f'{cell.name}: test stop time {stop_time} not in UTC format in {source}')


def _validate_test_outcome(test_outcome: str, fwd_test_disp: str, rvrs_test_disp: str, cell: CloudCell, errors: List[str], source: str):
    log_debug(f'Validating test outcome for {cell.name} in {source}')
    test_outcome = test_outcome.lower()
    fwd_test_disp = fwd_test_disp.lower()
    rvrs_test_disp = rvrs_test_disp.lower()

    if fwd_test_disp == 'pass' and rvrs_test_disp == 'pass' and test_outcome != 'pass':
        errors.append(f'{cell.name}: test outcome is {test_outcome} but it should be pass '
                      f'(as fwd_test_disp={fwd_test_disp} and rvrs_test_disp={rvrs_test_disp}) in {source}')
    elif (fwd_test_disp != 'pass' or rvrs_test_disp != 'pass') and test_outcome == 'pass':
        errors.append(f'{cell.name}: test outcome is pass but it should not be pass '
                      f'(as fwd_test_disp={fwd_test_disp} and rvrs_test_disp={rvrs_test_disp}) in {source}')


def _validate_antennas_results_from_api(antennas_results: List[Dict], cell: CloudCell, errors: List[str]):
    log_debug(f'Validating antennas test results for {cell.name} in API response')
    expected_keys = ['vswr', 'rssi_dbm', 'sinr_db', 'rtwp', 'fwd_etpw', 'fwd_et_pd_bm']

    for antenna_result in antennas_results:
        antenna_id = antenna_result['antl_id'] if antenna_result['antl_id'] is not None else antenna_result['phyant_id']

        for expected_key in expected_keys:
            value = antenna_result[expected_key]

            if expected_key not in antenna_result:
                errors.append(f'{cell.name}: missing {expected_key} value in test result for antenna {antenna_id} in API response')
            elif value != '-' and not is_measurement_numeric(value):
                errors.append(f'{cell.name}: {expected_key} value {value} is neither a number nor - in API response')


def _validate_antennas_results_from_config(antennas_results: List[Dict], cell: CloudCell, errors: List[str]):
    log_debug(f'Validating antennas test results for {cell.name} in DU configuration')
    expected_keys = ['vswr', 'rssi', 'sinr', 'fwdETPW', 'rtwp', 'fwdETPdBm']

    for antenna_result in antennas_results:
        for expected_key in expected_keys:
            value = antenna_result[expected_key]

            if expected_key not in antenna_result:
                antenna_id = antenna_result['antlId']
                errors.append(f'{cell.name}: missing {expected_key} value in test result for antenna {antenna_id} in DU configuration')
            elif antenna_result[expected_key] != '-' and not is_measurement_numeric(antenna_result[expected_key]):
                errors.append(f'{cell.name}: {expected_key} value {value} is neither a number nor - in DU configuration')
